'use strict';

// MODULES //

import copysignf from '@stdlib/math-base-special-copysignf';
import { assign as sincosf } from '@stdlib/math-base-special-sincosf';
import isnanf from '@stdlib/math-base-assert-is-nanf';
import isInfinitef from '@stdlib/math-base-assert-is-infinitef';
import expf from '@stdlib/math-base-special-expf';
import f32 from '@stdlib/number-float64-base-to-float32';
import PINF from '@stdlib/constants-float32-pinf';
import NINF from '@stdlib/constants-float32-ninf';


// VARIABLES //

var WORKSPACE = [ 0.0, 0.0 ];


// MAIN //

/**
* Evaluates the exponential function for a single-precision complex floating-point number and assigns results to a provided output array.
*
* @param {number} re - real component
* @param {number} im - imaginary component
* @param {Collection} out - output array
* @param {integer} strideOut - stride length
* @param {NonNegativeInteger} offsetOut - starting index
* @returns {Collection} output array
*
* @example
* import Float32Array from '@stdlib/array-float32';
*
* var out = assign( 0.0, 0.0, new Float32Array( 2 ), 1, 0 );
* // returns <Float32Array>[ 1.0, 0.0 ]
*/
function assign( re, im, out, strideOut, offsetOut ) {
	var e;

	if ( isnanf( re ) ) {
		out[ offsetOut ] = NaN;
		out[ offsetOut+strideOut ] = ( im === 0.0 ) ? im : NaN;
		return out;
	}
	if ( isInfinitef( im ) ) {
		if ( re === PINF ) {
			out[ offsetOut ] = NINF;
			out[ offsetOut+strideOut ] = NaN;
			return out;
		}
		if ( re === NINF ) {
			out[ offsetOut ] = -0.0;
			out[ offsetOut+strideOut ] = copysignf( 0.0, im );
			return out;
		}
		out[ offsetOut ] = NaN;
		out[ offsetOut+strideOut ] = NaN;
		return out;
	}
	e = expf( re );
	if ( im === 0.0 ) {
		out[ offsetOut ] = e;
		out[ offsetOut+strideOut ] = im;
		return out;
	}
	sincosf( im, WORKSPACE, 1, 0 );
	out[ offsetOut ] = f32( WORKSPACE[ 1 ] * e );
	out[ offsetOut+strideOut ] = f32( WORKSPACE[ 0 ] * e );
	return out;
}


// EXPORTS //

export default assign;
